#!/usr/bin/env bash
# manual_setup.sh — Manual setup guide for AJD (no AI agent)
# Run this after curl install.sh when you detect NO agents on your machine.
# Generated by AJD installation script or copied from docs folder.

set -euo pipefail

AJD_HOME="${1:-${HOME}/.ajd}"

echo "=== AJD Manual Setup Guide ==="
echo ""
echo "This guide helps you configure AJD without an AI agent."
echo "If you have agent configs (Hermes, Claude, etc.), see AGENTS.md instead."
echo ""

# Step 1: Check if projects.json exists
if [ ! -f "$AJD_HOME/projects.json" ]; then
    echo "❌ Missing $AJD_HOME/projects.json"
    echo "Run this first:"
    echo "   cd $AJD_HOME"
    echo "   cat app/projects.example.json > projects.json"
    echo "   vi projects.json"
    echo ""
    echo "Copy the template, fill your project paths, then run this setup again."
    exit 1
fi

# Step 2: Show current AJD_URL config state
echo "=== Current Configuration ==="
echo ""
echo "AJD should be running at:"
echo "   http://localhost:5080/"
echo ""
echo "To change the port, stop the service, set PORT=nnnn in startup, then restart."

# Step 3: Show how to validate setup
echo ""
echo "=== How to Verify AJD Setup ==="
echo ""
echo "1. Check if AJD is running:"
echo "   curl -s http://localhost:5080/api/state | head -c 200"
echo ""
echo "2. Expected output (first few lines of JSON):"
echo '   {"projects": {"<YOUR_PROJECT>": {...}, ... }, "services": [...], "schedulers": [...]}'
echo ""

# Step 4: Test the heartbeat endpoint
echo "3. Submit a test heartbeat:"
echo "   curl -X POST http://localhost:5080/api/heartbeat \\"
echo "     -H 'Content-Type: application/json' \\"
echo "     -d '{\\\"project\\\":\\\"manual_setup_test\\\",\\\"status\\\":\\\"ok\\\",\\\"note\\\":\\\"Test heartbeat from manual config\\\"}'"
echo ""

# Step 5: Show where to edit project config
echo "4. Edit your projects.json:"
echo "   cd $AJD_HOME"
echo "   vi projects.json"
echo ""
echo "See app/projects.example.json for the schema reference."
echo ""

# Step 6: Cron examples (no agent)
echo "=== Adding Jobs to Crontab ==="
echo ""
echo "After editing, add your cron jobs. Example for a project at $AJD_HOME:"
echo ""
cat << 'CRONTAB_EX'
# AJD Example cron job
0 8 * * * [ -f /home/username/.ajd/projects.json ] && cd /home/username/.ajd/app && python3 app.py --port 5080 &
0 9 * * * curl -X POST http://localhost:5080/api/heartbeat -H 'Content-Type: application/json' -d '{"project":"daily_report","status":"ok"}' || echo "Heartbeat failed, check /tmp/cron_error.log"
CRONTAB_EX
echo ""

# Step 7: Show where to log errors
echo "5. Error logging:"
echo "   Logs are at: $AJD_HOME/data/logs/server.log"
echo "   Add cron error logs:"
echo "      >> /home/username/.ajd/data/logs/cron_error.log 2>&1 || true"
echo ""

# Step 8: Check port for conflicts
echo "6. Port conflict check:"
if [ -n "$(cat /proc/net/tcp | grep ':13C0')" ]; then
    echo "   ⚠️  Warning: Port 5080 may be in use"
else
    echo "   ✅ Port 5080 is free"
fi

# Summary
echo ""
echo "=== Manual Setup Complete ==="
echo ""
echo "Summary:"
echo "   • AJD directory: $AJD_HOME"
echo "   • Projects config: $AJD_HOME/projects.json"
echo "   • Dashboard URL: http://localhost:5080/"
echo "   • Service logs: $AJD_HOME/data/logs/server.log"
echo ""
echo "Next steps:"
echo "   1. Edit $AJD_HOME/projects.json with your project paths"
echo "   2. Add cron jobs to run your project scripts"
echo "   3. Verify with: curl http://localhost:5080/api/state"
echo ""
echo "For agent-based setup, delete this instruction and see AGENTS.md instead."
